const { withAppBuildGradle } = require("@expo/config-plugins");

/**
 * Signs release builds with the Play Store upload key instead of Expo's debug
 * keystore.
 *
 * `android/` is gitignored and regenerated by `expo prebuild`, so a hand edit
 * to build.gradle would be silently lost; this plugin re-applies it on every
 * prebuild. The secrets never touch the repo: they are read at build time from
 * `~/.gradle/gradle.properties` (FOODPAL_UPLOAD_STORE_FILE, FOODPAL_UPLOAD_KEY_ALIAS,
 * FOODPAL_UPLOAD_STORE_PASSWORD, FOODPAL_UPLOAD_KEY_PASSWORD).
 *
 * When those properties are absent the release build falls back to the debug
 * key, so Firebase App Distribution builds on another machine still work — but
 * such a build cannot be uploaded to Play.
 *
 * Mirrors meal-host-rider/plugins/withReleaseSigning.js (RIDER_UPLOAD_* there).
 */
const MARKER = "// withReleaseSigning";

const SIGNING_CONFIG = `
        release { ${MARKER}
            if (project.hasProperty('FOODPAL_UPLOAD_STORE_FILE')) {
                storeFile file(FOODPAL_UPLOAD_STORE_FILE)
                storePassword FOODPAL_UPLOAD_STORE_PASSWORD
                keyAlias FOODPAL_UPLOAD_KEY_ALIAS
                keyPassword FOODPAL_UPLOAD_KEY_PASSWORD
            }
        }`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents;
    if (gradle.includes(MARKER)) return cfg;

    // Add the release signing config after the debug one.
    gradle = gradle.replace(
      /(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/,
      `$1${SIGNING_CONFIG}`
    );

    // Point the release build type at it, keeping the debug fallback.
    gradle = gradle.replace(
      /(release\s*\{[^{}]*?)signingConfig signingConfigs\.debug/,
      `$1signingConfig project.hasProperty('FOODPAL_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug`
    );

    if (!gradle.includes(MARKER) || !gradle.includes("signingConfigs.release")) {
      throw new Error("withReleaseSigning: build.gradle layout changed; update the plugin.");
    }
    cfg.modResults.contents = gradle;
    return cfg;
  });
};
